-- drop table products;
-- drop table products_variants ;

 create table products(
 	product_id INT  auto_increment,
 	sku VARCHAR(9) NOT NULL unique ,
 	name VARCHAR(50) NOT NULL,
 	category VARCHAR(20) NOT NULL,
 	brand VARCHAR(25),
 	description VARCHAR(300),
 	gender VARCHAR(20),
	base_price DECIMAL(5,2) NOT NULL check(base_price >=0),
 	rating DECIMAL(3,1) check(rating>=0.0 and rating <=10.0),
 	review_count INT check(review_count>=0) default 0,
 	active VARCHAR(5) NOT NULL default "TRUE",
	primary key(product_id)
 );
 
 
